    """Point mutation: perturb a single node's value/operator."""
    offspring = parent.copy()
    nodes = offspring.get_all_nodes()
    if len(nodes) <= 1:
        return offspring
    mp = random.randint(0, len(nodes) - 1)
    node, par, ci = nodes[mp]
