        same_arity = [n for n in OPERATOR_NAMES if OPERATORS[n][1] == arity and n != node.value]
        if same_arity:
            node.value = random.choice(same_arity)
    return offspring


def hoist_mutation(parent, n_features, max_depth=17):
    """Hoist mutation: replace subtree with a smaller subtree from itself.
    Reduces bloat while preserving structure."""
    offspring = parent.copy()
    ts = offspring.size()
    if ts <= 3:
        return offspring
    all_nodes = offspring.get_all_nodes()
    root_idx = random.randint(1, len(all_nodes) - 1)
    root_node, root_par, root_ci = all_nodes[root_idx]
    subtree_nodes = root_node.get_all_nodes()
    if len(subtree_nodes) <= 1:
        return offspring
    hoist_idx = random.randint(1, len(subtree_nodes) - 1)
    hoist_sub = subtree_nodes[hoist_idx][0].copy()
    if root_par is not None:
        root_par.children[root_ci] = hoist_sub
    else:
        offspring = hoist_sub
    return offspring

