def evolve_one_generation(population, fitnesses, X_train, y_train,
                          n_features, pop_size,
                          crossover_rate=0.9, mutation_rate=0.05,
                          max_depth=17):
    """GP generation with adaptive parsimony + Pareto-lexicase selection,
    plus point mutation and hoist mutation operators."""
    new_population = []
    lengths = np.array([t.size() for t in population], dtype=float)
    rf = np.array(fitnesses, dtype=float)
    lv = float(np.var(lengths))
    if lv > 1e-15:
        pc = max(min(float(np.cov(lengths, rf)[1, 0]) / lv, 0.001), 0.0)
    else:
        pc = 0.0
    penalized = rf + pc * lengths
    ei = int(np.argmin(fitnesses))
    new_population.append(population[ei].copy())
    errors = np.empty((len(population), X_train.shape[0]))
    for i, tree in enumerate(population):
        errors[i] = np.abs(y_train - safe_evaluate(tree, X_train))
    while len(new_population) < pop_size:
        r = random.random()
        if r < crossover_rate:
            p = selection(population, fitnesses, 2, _errors=errors, _penalized=penalized)
            child = crossover(p[0], p[1], n_features, max_depth)
        elif r < crossover_rate + mutation_rate:
            p = selection(population, fitnesses, 1, _errors=errors, _penalized=penalized)
            child = mutation(p[0], n_features, max_depth)
        elif r < crossover_rate + mutation_rate + 0.02:
            p = selection(population, fitnesses, 1, _errors=errors, _penalized=penalized)
            child = point_mutation(p[0], n_features, max_depth)
        elif r < crossover_rate + mutation_rate + 0.04:
            p = selection(population, fitnesses, 1, _errors=errors, _penalized=penalized)
            child = hoist_mutation(p[0], n_features, max_depth)
        else:
            p = selection(population, fitnesses, 1, _errors=errors, _penalized=penalized)
            child = p[0]
        new_population.append(child)
    return new_population[:pop_size]

